afterHooks.code:
if (driver) {
    if (this.currentTest.state === "failed") {
        const img = await driver.takeScreenshot();
        const name = this.currentTest.title.replace(/[^a-z0-9]/gi, "_");
        fs.writeFileSync(`fail_${name}.png`, img, "base64");
    }
    await driver.quit();
}

